insert into public.reference_passages
  (id, source_id, branch, personnel_category, occupation_code, occupation_title, section_type, rank_band, components, heading, chapter, body, body_sha256, pdf_page_start, pdf_page_end, printed_page, sort_order, effective_from, effective_to, cumulative, skill_level)
values
  ('d51734c8-3af2-5ad3-81f4-db68d180fd32', '1f2232c2-daa4-5614-9be4-ce5c7b8d8565', 'Army', 'officer', '26A', 'NETWORK SYSTEMS ENGINEERING', 'training', 'O-3', null, 'Captain Development — Education', 'Data Network Engineering Functional Area (FA26) career pamphlet, DA PAM 600-3 chapter (24 July 2026)', 'Selected officers should attend NSEC or DSEC and serve in their assigned AOC billets as soon as possible after FA 26 designation. Officers who have not previously completed a basic branch Captain’s Career Course will attend SCCC at Fort Gordon, GA either before or after completing NSEC or DSEC. Successful completion of CCC Common Core modules is the minimum requirement for AOC 26A/B. Direct commission officers are required to attend the full length of SCCC. Recommended industry certificates include ITIL Foundations and approved 8140.03 DCWF qualifications for work roles at the intermediate level of proficiency.', 'd86c120f8df3e6ee5d104cbed665acff5d76049ecae37a061eade5f24a90d8bb', 7, 7, null, 0, null, null, false, null),
  ('e1103727-79ac-52cb-a18f-5fb8adc25013', '1f2232c2-daa4-5614-9be4-ce5c7b8d8565', 'Army', 'officer', '26A', 'NETWORK SYSTEMS ENGINEERING', 'development', 'O-3', null, 'Captain Development — Typical Developmental Assignments', 'Data Network Engineering Functional Area (FA26) career pamphlet, DA PAM 600-3 chapter (24 July 2026)', 'FA 26 candidates will transfer from their basic branch to begin FA qualification within 12 months of designation. All FA 26 positions are Key Developmental (KD) assignments. Officers should strive to complete a minimum of 24 months in AOC 26A or AOC 26B assignments before completing a TWI or ACS. Typical developmental assignments at captain include:', '98b588765ed6631676cc673d40505478da3b1fffe251b6499c534f51eff5d80f', 7, 7, null, 1, null, null, false, null),
  ('b091cb0b-885c-5c03-b72b-6b59982d7bf3', '1f2232c2-daa4-5614-9be4-ce5c7b8d8565', 'Army', 'officer', '26A', 'NETWORK SYSTEMS ENGINEERING', 'development', 'O-3', null, 'Captain Development — AOC 26A', 'Data Network Engineering Functional Area (FA26) career pamphlet, DA PAM 600-3 chapter (24 July 2026)', '(a) Network Systems Engineer in a Division (DIV), Army Air and Missile Defense Command (AAMDC), Army Service Component Command (ASCC), Signal Battalion (BN), Brigade (BDE) or Command (CMD), Military Intelligence (MI) BDE, Regional Cyber Center (RCC), U.S. Army Network Enterprise Technology Command (NETCOM), US Army Information Systems Engineering Command (ISEC)
(b) 60th Signal Battalion (BN) (Offensive Cyber Operations)
(c) Cyber Protection Team (CPT)
(d) Infrastructure Support OIC, USA Cyber Warfare Support Battalion
(e) Test Officer, USA Operational Test Command', '98b1b47a3e3650e189d1493979e4dbbdda5872fd63e0dbcaf04e71dad7b81eed', 7, 7, null, 2, null, null, false, null),
  ('1ee9e10f-6c1d-5a2b-85a4-d0f7db50e664', '1f2232c2-daa4-5614-9be4-ce5c7b8d8565', 'Army', 'officer', '26A', 'NETWORK SYSTEMS ENGINEERING', 'development', 'O-3', null, 'Captain Development — AOC 26B', 'Data Network Engineering Functional Area (FA26) career pamphlet, DA PAM 600-3 chapter (24 July 2026)', '(a) Data Systems Engineer in a Brigade Combat Team (BCT), DIV, CMD, SOF/CA, Field Artillery BDE, AAMDC, ASCC
(b) 60th Signal BN (Offensive Cyber Operations)
(c) Cyberspace Operations and Integration Center (COIC)
(d) Data Systems Engineer in a Signal BN, BDE, or CMD; MI BDE, RCC, NETCOM, ARCYBER, DISA
(e) Knowledge Sys Engr in Multi-Domain Task Force (MDTF), AAMDC, ASCC
(f) Security Force Assistance Brigade (SFAB)
(g) USA Enterprise Cloud Management Agency (ECMA)
(h) USA Joint Modernization Command (JMC)', '4c7d3eb3725df9b4d7e84df2c8a38a9a51246abd265688d1e7ac3902303dc19c', 7, 7, null, 3, null, null, false, null),
  ('48777768-7978-5f69-a7a1-e54f0703b1ff', '1f2232c2-daa4-5614-9be4-ce5c7b8d8565', 'Army', 'officer', '26A', 'NETWORK SYSTEMS ENGINEERING', 'assignments', 'O-3', null, 'Captain Development — Developmental Assignments', 'Data Network Engineering Functional Area (FA26) career pamphlet, DA PAM 600-3 chapter (24 July 2026)', 'Due to the technical nature and need for early development in this AOC, FA 26 captains usually will not serve in branch immaterial or other assignments outside the AOC. However, captains may be selected for fully funded Advanced Civilian Schooling (ACS) or Training with Industry (TWI) in an AOC 26A or AOC 26B related discipline after demonstrating readiness for the next promotion board. Graduates of either program will incur a follow-on utilization assignment in an Army Educational Requirements System (AERS) coded position. Additional education opportunities include the Computer Network Operations Development Program (CNODP) and other Army-supported education/fellowship programs. Nominative assignments such as Special Missions Detachment (SMD), Joint Special Operations Command (JSOC), National Security Agency, White House Communications Agency (WHCA), 160th Special Operations Aviation Regiment (SOAR), 75th Ranger Regiment, US Military Academy (USMA), Army Artificial Intelligence Integration Center (AI2C), and Army Software Factory should be considered after completion of 24 months in a non-nominative assignment.', '5241625732f5b364a710418bd863e1e99f8fb4a966d82b218b91ee78fe102f26', 7, 7, null, 4, null, null, false, null),
  ('8e8c9dc6-5b52-574c-b063-2da68dd97443', '1f2232c2-daa4-5614-9be4-ce5c7b8d8565', 'Army', 'officer', '26A', 'NETWORK SYSTEMS ENGINEERING', 'self_development', 'O-3', null, 'Captain Development — Self-development', 'Data Network Engineering Functional Area (FA26) career pamphlet, DA PAM 600-3 chapter (24 July 2026)', 'AOC 26A captains should pursue self-development through graduate-level education, industry certifications, and completion of online training related to 5G and software-defined networking, computer science, cyberspace operations, cybersecurity, and other relevant disciplines. AOC 26B captains should pursue self-development through graduate-level education, industry certifications, and completion of online training related to Server management, Data analytics, cloud computing, artificial intelligence, etc. Due to the rapid changes in technology, captains are encouraged to join professional organizations and subscribe to journals to stay current with industry trends and advancements. Captains are also encouraged to conduct research and write articles for professional and military publications. Obtaining the Certified Information Systems Security Professional (CISSP) certification is highly encouraged for AOC 26A, and Cybersecurity Analyst (CySA) for AOC 26B satisfies cybersecurity requirements IAW DOD 8140.03 DCWF. Training is available through Army Credentialing Opportunities On-Line (COOL) at https://www.cool.osd.mil/army/index.htm. Additional cost and no- cost civilian IT training and education courses are available via the internet.', '95d4d070c96f74cc0349acc83bfe5ad3c5e9b9a6685272b01d50e8167c3a64a0', 7, 8, null, 5, null, null, false, null),
  ('fe068627-ebaa-5c94-8a4e-03f27beed214', '1f2232c2-daa4-5614-9be4-ce5c7b8d8565', 'Army', 'officer', '26A', 'NETWORK SYSTEMS ENGINEERING', 'development', 'O-3', null, 'Captain Development — Desired Experience', 'Data Network Engineering Functional Area (FA26) career pamphlet, DA PAM 600-3 chapter (24 July 2026)', '(a) AOC 26A captains should demonstrate competency in basic network engineering, assessment, managing, and planning and experience in conducting current network operations, including dynamic network defense and security. Assignments should enable captains to gain knowledge, skills, and behaviors (KSBs) to accurately evaluate technologies and prepare technical specification documents based on those evaluations. Desired experience at the rank of captain is 24 months in at least one AOC 26A typical developmental assignment to gain the necessary technical skills, operational background and project management skills.
(b) AOC 26B captains should demonstrate competencies in data systems and services planning, analyzing, and management, and experience in conducting information systems security. Assignments should enable captains to acquire knowledge, skills, and abilities in data systems management, information security, and information dissemination management in support of an immediate headquarters. Desired experience at the rank of captain is 24 months in at least one AOC 26B typical developmental assignment to gain the necessary technical skills, operational background and project management skills.', '565b8acb4410f7cc8887deb447498dd4964949a3147f8965e9dc4dba23215ab3', 8, 8, null, 6, null, null, false, null),
  ('cea60f3a-6688-5b28-b891-f2f5fb9e5321', '1f2232c2-daa4-5614-9be4-ce5c7b8d8565', 'Army', 'officer', '26A', 'NETWORK SYSTEMS ENGINEERING', 'training', 'O-4', null, 'Major — Education', 'Data Network Engineering Functional Area (FA26) career pamphlet, DA PAM 600-3 chapter (24 July 2026)', 'All FA 26 majors must complete Intermediate Level Education (ILE). ILE requirements for FA 26 officers include the ILE Common Core and the AOC 26A or AOC 26B qualification course (NSEC or DSEC). If not previously qualified as a captain, FA 26 majors must also complete the functional area qualification training. Officers can complete functional area qualification training and ILE Common Core in any sequence.', 'c957ab5e4d5ac4fd01ab2390bfff0d33331f91130c174bd240883c1871a3434e', 8, 8, null, 7, null, null, false, null),
  ('4bddb35a-c741-5a34-86bb-a1221fc3534f', '1f2232c2-daa4-5614-9be4-ce5c7b8d8565', 'Army', 'officer', '26A', 'NETWORK SYSTEMS ENGINEERING', 'development', 'O-4', null, 'Major — Typical Developmental Assignments', 'Data Network Engineering Functional Area (FA26) career pamphlet, DA PAM 600-3 chapter (24 July 2026)', 'All FA 26 positions are KD assignments. Officers should strive to complete an aggregate of 24 to 36 months in typical developmental assignments before competing for TWI or ACS. Typical developmental assignments at Major include:', 'e69090a88beb9b7791b9695bcdb410c9ba737c340ab5a282b2f6773c36d3e21a', 8, 8, null, 8, null, null, false, null),
  ('9b338718-ec59-5a03-b5e9-6b2328abe3b3', '1f2232c2-daa4-5614-9be4-ce5c7b8d8565', 'Army', 'officer', '26A', 'NETWORK SYSTEMS ENGINEERING', 'development', 'O-4', null, 'Major — AOC 26A', 'Data Network Engineering Functional Area (FA26) career pamphlet, DA PAM 600-3 chapter (24 July 2026)', '(a) Sr Network Sys Engr in a DIV, Corps, ASCC, COCOM, Signal BDE or CMD, MI BDE, RCC, NETCOM, ARCYBER, DISA, Joint or Higher
(b) 60th Signal BN (Offensive Cyber Operations)
(c) COIC
(d) Requirements Officer, Future Capabilities Development Command and Control (FCD C2)
(e) White House Communications Agency (WHCA)
(f) North American Aerospace Defense Command
(g) Sr Network Systems Engineer, Program Executive Office (PEO), Enterprise Info Sys
(h) USA AI2C', '072859842a7327640e6c49dc8331cec888a89795d0a56ef2ef110056bd80d335', 8, 8, null, 9, null, null, false, null),
  ('244031ed-6ee9-5836-8d7c-362b1d6c8eab', '1f2232c2-daa4-5614-9be4-ce5c7b8d8565', 'Army', 'officer', '26A', 'NETWORK SYSTEMS ENGINEERING', 'development', 'O-4', null, 'Major — AOC 26B', 'Data Network Engineering Functional Area (FA26) career pamphlet, DA PAM 600-3 chapter (24 July 2026)', '(a) Sr Data Sys Engr in a Division, Corps, ASCC, Signal BDE or CMD, MI BDE, NETCOM, DISA
(b) 60th Signal BN (Offensive Cyber Operations)
(c) COIC
(d) Sr Info Sys Engr, FCD-C2
(e) Sr Information Assurance Officer in a DIV, Sustainment CMD, ASCC, RCC
(f) WHCA
(g) National Ground Intelligence Center (NGIC)
(h) USA ECMA', 'f4cd4e0b8aa9ecaf64bae3a809c0ac2ac950f6881a0d3ed0810266ef153d0536', 8, 8, null, 10, null, null, false, null),
  ('c449081b-f971-5aa3-911a-967cbb0630df', '1f2232c2-daa4-5614-9be4-ce5c7b8d8565', 'Army', 'officer', '26A', 'NETWORK SYSTEMS ENGINEERING', 'assignments', 'O-4', null, 'Major — Developmental Assignments', 'Data Network Engineering Functional Area (FA26) career pamphlet, DA PAM 600-3 chapter (24 July 2026)', 'AOC 26A majors’ training, education, and development should focus on data network engineering. AOC 26B majors’ training, education, and development should focus on data systems engineering. Due to the technical nature of these AOCs, AOC 26A and AOC 26B majors usually will not serve in branch immaterial or other assignments outside of the AOC. Generally, FA 26 majors should not seek repetitive assignments as FA 26, striving for various experiences at different levels of operation (e.g., tactical, operational, strategic, joint, and multi-national). Majors may be selected for fully funded ACS or TWI programs. Graduates of either program will incur a follow-on utilization assignment. FA 26 majors with operational experience are well suited for assignments in support of career field growth and personnel management, including Career Managers, Career Program Managers and Instructors at USMA and the US Army Signal School. FA 26 officers are encouraged to seek opportunities that enhance the officer’s understanding of the global network environment associated with JADO assignments. Additional education opportunities include the Defense Advanced Research Projects Agency (DARPA) Service Chiefs Internship and other Army-supported education/fellowship programs.', 'd2be4f1b05b8a702fc0c721e33ae1145f259927d81a43b3eddc390dea5cf69f9', 8, 9, null, 11, null, null, false, null),
  ('59a422c8-1d02-5aa6-86ea-21770ed0b7da', '1f2232c2-daa4-5614-9be4-ce5c7b8d8565', 'Army', 'officer', '26A', 'NETWORK SYSTEMS ENGINEERING', 'self_development', 'O-4', null, 'Major — Self-development', 'Data Network Engineering Functional Area (FA26) career pamphlet, DA PAM 600-3 chapter (24 July 2026)', 'FA 26 majors should continue to pursue self-development in accordance with assignment, unit mission and equipment, education, and emerging technologies. AOC 26A should pursue self- development in the areas of hybrid software defined networks, and unified network platforms along with developing a holistic vision of a zero-trust infrastructure designed to drive the integration of communication and computing resources in a continuous data-centric network fabric. AOC 26B majors should pursue self- development in the areas of data architecture, artificial intelligence, and machine learning along with developing a holistic vision of cloud architecture and database structure which enable the development and management of total data systems.', 'caf92a6451a980933f946ba2aae4c6e1f0ba62f33901b86fa3de93d4e270f61d', 9, 9, null, 12, null, null, false, null),
  ('524f20d4-8ba9-51c2-9a80-8bf7e93d9324', '1f2232c2-daa4-5614-9be4-ce5c7b8d8565', 'Army', 'officer', '26A', 'NETWORK SYSTEMS ENGINEERING', 'development', 'O-4', null, 'Major — Desired Experience', 'Data Network Engineering Functional Area (FA26) career pamphlet, DA PAM 600-3 chapter (24 July 2026)', '(a) AOC 26A majors should demonstrate competency and advanced skills in network engineering, assessment, managing, planning, and experience in conducting current network operations and defending/securing networks. In addition, field grade development should enable AOC 26As to hone knowledge, skills, and abilities in accurately evaluating technologies and preparing technical specification documents based on these evaluations. Successful completion of ILE and 24 to 36 months of experience in increasing responsibility and professional development assignments will prepare majors for service as a lieutenant colonel.
(b) AOC 26B majors should demonstrate competency and advanced skills in data architecture planning and development and implementation of information assurance concepts and principles. Field grade development should enable AOC 26Bs to hone knowledge, skills, and abilities to perform system analysis, develop response procedures, perform accreditation processes, and integrate data and IT systems in all JADO environments. Successful completion of ILE and 24 to 36 months of experience in increasing responsibility and professional development assignments will prepare majors for service as a lieutenant colonel.', 'd3e1cb9612076a7cb29cce87981640142621cd0e3b8b6194628671367a1c3fc0', 9, 9, null, 13, null, null, false, null),
  ('7b8a7ff7-97b0-5b3c-9a01-f5e066b08f9f', '1f2232c2-daa4-5614-9be4-ce5c7b8d8565', 'Army', 'officer', '26A', 'NETWORK SYSTEMS ENGINEERING', 'training', 'O-5', null, 'Lieutenant Colonel — Education', 'Data Network Engineering Functional Area (FA26) career pamphlet, DA PAM 600-3 chapter (24 July 2026)', 'There are no additional educational requirements for lieutenant colonels, however, a Master of Science degree in an IT-related field is highly encouraged. Successful completion of JPME II is desired.', 'a64b2d1b55128ae435cee73cc2bef5329e814247f94b74ce7578053c7bfe014e', 9, 9, null, 14, null, null, false, null),
  ('fdee21e3-3ac3-5d3c-96b9-27053fa3733e', '1f2232c2-daa4-5614-9be4-ce5c7b8d8565', 'Army', 'officer', '26A', 'NETWORK SYSTEMS ENGINEERING', 'development', 'O-5', null, 'Lieutenant Colonel — Typical Developmental Assignments', 'Data Network Engineering Functional Area (FA26) career pamphlet, DA PAM 600-3 chapter (24 July 2026)', 'All FA 26 lieutenant colonel positions are considered KD assignments. Certain positions are designated as Key Nominative Billets (KNB) or Centralized Selection List (CSL) billets, and officers are centrally selected to fill these positions. Eligible officers will be notified by MILPER message and are encouraged to compete when in the zone of consideration for these assignments. Officers should strive to complete an aggregate of 24 to 36 months in typical developmental assignments before consideration for more senior lieutenant colonel assignments. Typical developmental, CSL or KNB assignments at lieutenant colonel include:', '796b883f40cf4d3ad75554fd7d0c7aa1f421f76f139ebcb40404121d4cec7a2a', 9, 9, null, 15, null, null, false, null),
  ('456f2d3a-d179-5372-bc62-e33350635ff4', '1f2232c2-daa4-5614-9be4-ce5c7b8d8565', 'Army', 'officer', '26A', 'NETWORK SYSTEMS ENGINEERING', 'development', 'O-5', null, 'Lieutenant Colonel — CSL for AOC 26A and AOC 26B', 'Data Network Engineering Functional Area (FA26) career pamphlet, DA PAM 600-3 chapter (24 July 2026)', 'Director, Regional Cyber Center (RCC)', '126adb863ef6458efd1e23b422d5f156e7312e21b77fe5249bc2f953e7e91651', 9, 9, null, 16, null, null, false, null),
  ('c77885c4-9cbd-52d2-98b3-b53cfb7a739d', '1f2232c2-daa4-5614-9be4-ce5c7b8d8565', 'Army', 'officer', '26A', 'NETWORK SYSTEMS ENGINEERING', 'development', 'O-5', null, 'Lieutenant Colonel — AOC 26A', 'Data Network Engineering Functional Area (FA26) career pamphlet, DA PAM 600-3 chapter (24 July 2026)', '(a) Chief Network Sys Engr in a Corps, ASCC, Signal Brigade, RCC, NETCOM, ARCYBER, DISA, COCOM, Joint, DOD Level
(b) COIC
(c) The Office of the Chief Information Officer
(d) Chief, Network & Cyber Branch, USA JMC
(e) Sr. Test Officer, USA Operational Test Command
(f) USA AI2C', '9b5db754545126e62d0d23248e543f6e513140152bcfd2b4bd93b396ed6092e6', 9, 9, null, 17, null, null, false, null),
  ('5872b534-86be-5c01-b2f6-0e6832e63152', '1f2232c2-daa4-5614-9be4-ce5c7b8d8565', 'Army', 'officer', '26A', 'NETWORK SYSTEMS ENGINEERING', 'development', 'O-5', null, 'Lieutenant Colonel — AOC 26B', 'Data Network Engineering Functional Area (FA26) career pamphlet, DA PAM 600-3 chapter (24 July 2026)', '(a) Chief Data Sys Engr or Chief Info Assurance Officer in a Corps, ASCC, Signal BDE, NETCOM, DISA, or higher CMD
(b) COIC
(c) The Office of the Chief Information Officer
(d) USA JMC, Branch Chief MSN CMD SYS & APPS
(e) John F. Kennedy Special Warfare Center and School, G6/CIO
(f) National Defense University Military Faculty
(g) USA Futures CMD Application Group (SWFAC)', '3e9cadeae024577f8b1564d17321119fa92f974bad29ea3492d50bc7af44dd4f', 9, 10, null, 18, null, null, false, null),
  ('999467bb-9803-5bd7-add4-bef2321dc5eb', '1f2232c2-daa4-5614-9be4-ce5c7b8d8565', 'Army', 'officer', '26A', 'NETWORK SYSTEMS ENGINEERING', 'assignments', 'O-5', null, 'Lieutenant Colonel — Developmental Assignments', 'Data Network Engineering Functional Area (FA26) career pamphlet, DA PAM 600-3 chapter (24 July 2026)', 'Generally, FA 26 lieutenant colonels should not continue to seek repetitive assignments in their AOC, striving for various experiences at different levels of operation and concentrating their professional development in network systems engineering and data systems engineering. At lieutenant colonel, FA 26 officers may obtain developmental experience through TWI and Army fellowships. Select AOC 26A/B officers may serve developmental assignments within branch immaterial positions or related cross- branch/FA positions within the Signal Regiment. Based upon requirements, AOC 26A/B lieutenant colonels might be selected as Professors of Military Science. In addition, some AOC 26A/B lieutenant colonels may be chosen to participate in an IT-related Ph.D. program. All FA 26 officers are encouraged to seek developmental opportunities that enhance the officers’ understanding of the global network environment associated with JADO assignments to include achieving Joint Qualified Officer status. Additional education opportunities include the DARPA Service Chiefs Internship and DARPA Program Manager and other Army-supported education/fellowship programs.', 'e2f47be8973b38f07b01eab0176b2af1b78a5ac20c1e92efc374d250ab5a30b0', 10, 10, null, 19, null, null, false, null),
  ('ee8425ed-6007-5c06-a0c9-e45505c0fc9e', '1f2232c2-daa4-5614-9be4-ce5c7b8d8565', 'Army', 'officer', '26A', 'NETWORK SYSTEMS ENGINEERING', 'self_development', 'O-5', null, 'Lieutenant Colonel — Self-development', 'Data Network Engineering Functional Area (FA26) career pamphlet, DA PAM 600-3 chapter (24 July 2026)', 'AOC 26A lieutenant colonels should pursue aggressive self-development through graduate-level education, industry certifications, and completion of online training and courses related to networking, computer science, cyberspace operations, cybersecurity, and other relevant disciplines. Lieutenant colonels need to stay current on industry trends through trade associations, journals, and participation in DOD and industry-sponsored forums focused on evolving IT issues and advancements. Lieutenant colonels are also encouraged to research and write articles for professional and military publications. AOC 26B lieutenant colonels should complete the CIO, or CISO course offered free by the National Defense University, College either in resident or nonresident attendance. No-cost IT training is available through the Federal Virtual Training Environment (https://fedvte.usalearning.gov/). It is also encouraged that officers obtain the ITIL Foundations certification. Additional cost and no-cost IT training and education courses are available via the internet and Army COOL at https://www.cool.osd.mil/army/index.htm. Some officers may pursue a Ph.D. in a STEM discipline but prefer an IT-related discipline.', 'd0cd2314d3bd76bf5789fa40aa993c4e7d5c4b5d846294949a7c4442a3a0b9d2', 10, 10, null, 20, null, null, false, null),
  ('d9e0e32c-1610-5d63-a6a1-93e4db53a2da', '1f2232c2-daa4-5614-9be4-ce5c7b8d8565', 'Army', 'officer', '26A', 'NETWORK SYSTEMS ENGINEERING', 'development', 'O-5', null, 'Lieutenant Colonel — Desired Experience', 'Data Network Engineering Functional Area (FA26) career pamphlet, DA PAM 600-3 chapter (24 July 2026)', 'FA26 lieutenant colonels are highly encouraged to plan for and participate in the CSL process to compete for challenging yet impactful assignments. As the Army navigates the landscape of data- centric operations and establishes the Unified Network, FA 26 officers are uniquely qualified to hold specific positions that require both technical expertise and traditional leadership skills. While not prescribed for career development, performing well in CSL positions will positively position competitive FA26 officers for promotion to colonel and beyond.
(a) AOC 26A lieutenant colonels should demonstrate a high degree and mastery of telecommunications systems engineering. AOC 26A officers in the grade of lieutenant colonels serve as senior leaders and managers throughout the Army providing technical engineering guidance, applying network integration experience, emerging technology vision, and overall, Soldier mentorship mastered over many years in uniform as a network engineer. Assignments of increasing responsibility will continue to enhance their leadership skills and technical competencies in leading, managing, and integrating enterprise-wide communications networks and information services for the Army and JADO organizations.
(b) AOC 26B lieutenant colonels should continue to broaden their experiences and seek assignments that enhance their technical skills, knowledge, and executive leadership abilities. They are generally assigned to senior leadership and staff positions that fully utilize their Army knowledge and data systems engineering experience. AOC 26B lieutenant colonels should strive to serve in assignments that will broaden their previous experience through leading organizations that provide data systems and services throughout the Army and JADO organizations. They should demonstrate expertise in performing system analysis, developing and planning data architectures, implementing information assurance concepts and principles, and developing response procedures.', '35a80944d04edf6a5bb5252fb5c53397923113dec5e4cc601d757e22466dbc88', 10, 10, null, 21, null, null, false, null),
  ('bf9351d2-f8c1-536b-8961-5bee3a13fdb9', '1f2232c2-daa4-5614-9be4-ce5c7b8d8565', 'Army', 'officer', '26B', 'DATA SYSTEMS ENGINEERING', 'training', 'O-3', null, 'Captain Development — Education', 'Data Network Engineering Functional Area (FA26) career pamphlet, DA PAM 600-3 chapter (24 July 2026)', 'Selected officers should attend NSEC or DSEC and serve in their assigned AOC billets as soon as possible after FA 26 designation. Officers who have not previously completed a basic branch Captain’s Career Course will attend SCCC at Fort Gordon, GA either before or after completing NSEC or DSEC. Successful completion of CCC Common Core modules is the minimum requirement for AOC 26A/B. Direct commission officers are required to attend the full length of SCCC. Recommended industry certificates include ITIL Foundations and approved 8140.03 DCWF qualifications for work roles at the intermediate level of proficiency.', 'd86c120f8df3e6ee5d104cbed665acff5d76049ecae37a061eade5f24a90d8bb', 7, 7, null, 22, null, null, false, null),
  ('0fdb2730-9788-5b45-84a3-4cb8fd6ea429', '1f2232c2-daa4-5614-9be4-ce5c7b8d8565', 'Army', 'officer', '26B', 'DATA SYSTEMS ENGINEERING', 'development', 'O-3', null, 'Captain Development — Typical Developmental Assignments', 'Data Network Engineering Functional Area (FA26) career pamphlet, DA PAM 600-3 chapter (24 July 2026)', 'FA 26 candidates will transfer from their basic branch to begin FA qualification within 12 months of designation. All FA 26 positions are Key Developmental (KD) assignments. Officers should strive to complete a minimum of 24 months in AOC 26A or AOC 26B assignments before completing a TWI or ACS. Typical developmental assignments at captain include:', '98b588765ed6631676cc673d40505478da3b1fffe251b6499c534f51eff5d80f', 7, 7, null, 23, null, null, false, null),
  ('7f604043-72e1-5dd8-9562-d3370a8d9c2e', '1f2232c2-daa4-5614-9be4-ce5c7b8d8565', 'Army', 'officer', '26B', 'DATA SYSTEMS ENGINEERING', 'development', 'O-3', null, 'Captain Development — AOC 26A', 'Data Network Engineering Functional Area (FA26) career pamphlet, DA PAM 600-3 chapter (24 July 2026)', '(a) Network Systems Engineer in a Division (DIV), Army Air and Missile Defense Command (AAMDC), Army Service Component Command (ASCC), Signal Battalion (BN), Brigade (BDE) or Command (CMD), Military Intelligence (MI) BDE, Regional Cyber Center (RCC), U.S. Army Network Enterprise Technology Command (NETCOM), US Army Information Systems Engineering Command (ISEC)
(b) 60th Signal Battalion (BN) (Offensive Cyber Operations)
(c) Cyber Protection Team (CPT)
(d) Infrastructure Support OIC, USA Cyber Warfare Support Battalion
(e) Test Officer, USA Operational Test Command', '98b1b47a3e3650e189d1493979e4dbbdda5872fd63e0dbcaf04e71dad7b81eed', 7, 7, null, 24, null, null, false, null),
  ('a49c6ded-800f-59a1-a0d0-02633439152f', '1f2232c2-daa4-5614-9be4-ce5c7b8d8565', 'Army', 'officer', '26B', 'DATA SYSTEMS ENGINEERING', 'development', 'O-3', null, 'Captain Development — AOC 26B', 'Data Network Engineering Functional Area (FA26) career pamphlet, DA PAM 600-3 chapter (24 July 2026)', '(a) Data Systems Engineer in a Brigade Combat Team (BCT), DIV, CMD, SOF/CA, Field Artillery BDE, AAMDC, ASCC
(b) 60th Signal BN (Offensive Cyber Operations)
(c) Cyberspace Operations and Integration Center (COIC)
(d) Data Systems Engineer in a Signal BN, BDE, or CMD; MI BDE, RCC, NETCOM, ARCYBER, DISA
(e) Knowledge Sys Engr in Multi-Domain Task Force (MDTF), AAMDC, ASCC
(f) Security Force Assistance Brigade (SFAB)
(g) USA Enterprise Cloud Management Agency (ECMA)
(h) USA Joint Modernization Command (JMC)', '4c7d3eb3725df9b4d7e84df2c8a38a9a51246abd265688d1e7ac3902303dc19c', 7, 7, null, 25, null, null, false, null),
  ('48052977-0bc8-5f44-b5e1-b62100ba5e45', '1f2232c2-daa4-5614-9be4-ce5c7b8d8565', 'Army', 'officer', '26B', 'DATA SYSTEMS ENGINEERING', 'assignments', 'O-3', null, 'Captain Development — Developmental Assignments', 'Data Network Engineering Functional Area (FA26) career pamphlet, DA PAM 600-3 chapter (24 July 2026)', 'Due to the technical nature and need for early development in this AOC, FA 26 captains usually will not serve in branch immaterial or other assignments outside the AOC. However, captains may be selected for fully funded Advanced Civilian Schooling (ACS) or Training with Industry (TWI) in an AOC 26A or AOC 26B related discipline after demonstrating readiness for the next promotion board. Graduates of either program will incur a follow-on utilization assignment in an Army Educational Requirements System (AERS) coded position. Additional education opportunities include the Computer Network Operations Development Program (CNODP) and other Army-supported education/fellowship programs. Nominative assignments such as Special Missions Detachment (SMD), Joint Special Operations Command (JSOC), National Security Agency, White House Communications Agency (WHCA), 160th Special Operations Aviation Regiment (SOAR), 75th Ranger Regiment, US Military Academy (USMA), Army Artificial Intelligence Integration Center (AI2C), and Army Software Factory should be considered after completion of 24 months in a non-nominative assignment.', '5241625732f5b364a710418bd863e1e99f8fb4a966d82b218b91ee78fe102f26', 7, 7, null, 26, null, null, false, null),
  ('f8751e1b-8bef-5a93-99ef-cff8e45a1d73', '1f2232c2-daa4-5614-9be4-ce5c7b8d8565', 'Army', 'officer', '26B', 'DATA SYSTEMS ENGINEERING', 'self_development', 'O-3', null, 'Captain Development — Self-development', 'Data Network Engineering Functional Area (FA26) career pamphlet, DA PAM 600-3 chapter (24 July 2026)', 'AOC 26A captains should pursue self-development through graduate-level education, industry certifications, and completion of online training related to 5G and software-defined networking, computer science, cyberspace operations, cybersecurity, and other relevant disciplines. AOC 26B captains should pursue self-development through graduate-level education, industry certifications, and completion of online training related to Server management, Data analytics, cloud computing, artificial intelligence, etc. Due to the rapid changes in technology, captains are encouraged to join professional organizations and subscribe to journals to stay current with industry trends and advancements. Captains are also encouraged to conduct research and write articles for professional and military publications. Obtaining the Certified Information Systems Security Professional (CISSP) certification is highly encouraged for AOC 26A, and Cybersecurity Analyst (CySA) for AOC 26B satisfies cybersecurity requirements IAW DOD 8140.03 DCWF. Training is available through Army Credentialing Opportunities On-Line (COOL) at https://www.cool.osd.mil/army/index.htm. Additional cost and no- cost civilian IT training and education courses are available via the internet.', '95d4d070c96f74cc0349acc83bfe5ad3c5e9b9a6685272b01d50e8167c3a64a0', 7, 8, null, 27, null, null, false, null),
  ('0f40028b-4abb-580d-8923-4691c3650e4e', '1f2232c2-daa4-5614-9be4-ce5c7b8d8565', 'Army', 'officer', '26B', 'DATA SYSTEMS ENGINEERING', 'development', 'O-3', null, 'Captain Development — Desired Experience', 'Data Network Engineering Functional Area (FA26) career pamphlet, DA PAM 600-3 chapter (24 July 2026)', '(a) AOC 26A captains should demonstrate competency in basic network engineering, assessment, managing, and planning and experience in conducting current network operations, including dynamic network defense and security. Assignments should enable captains to gain knowledge, skills, and behaviors (KSBs) to accurately evaluate technologies and prepare technical specification documents based on those evaluations. Desired experience at the rank of captain is 24 months in at least one AOC 26A typical developmental assignment to gain the necessary technical skills, operational background and project management skills.
(b) AOC 26B captains should demonstrate competencies in data systems and services planning, analyzing, and management, and experience in conducting information systems security. Assignments should enable captains to acquire knowledge, skills, and abilities in data systems management, information security, and information dissemination management in support of an immediate headquarters. Desired experience at the rank of captain is 24 months in at least one AOC 26B typical developmental assignment to gain the necessary technical skills, operational background and project management skills.', '565b8acb4410f7cc8887deb447498dd4964949a3147f8965e9dc4dba23215ab3', 8, 8, null, 28, null, null, false, null),
  ('07b2f38c-89ef-514b-90ce-32cf801b2437', '1f2232c2-daa4-5614-9be4-ce5c7b8d8565', 'Army', 'officer', '26B', 'DATA SYSTEMS ENGINEERING', 'training', 'O-4', null, 'Major — Education', 'Data Network Engineering Functional Area (FA26) career pamphlet, DA PAM 600-3 chapter (24 July 2026)', 'All FA 26 majors must complete Intermediate Level Education (ILE). ILE requirements for FA 26 officers include the ILE Common Core and the AOC 26A or AOC 26B qualification course (NSEC or DSEC). If not previously qualified as a captain, FA 26 majors must also complete the functional area qualification training. Officers can complete functional area qualification training and ILE Common Core in any sequence.', 'c957ab5e4d5ac4fd01ab2390bfff0d33331f91130c174bd240883c1871a3434e', 8, 8, null, 29, null, null, false, null),
  ('e0275530-77e5-55cf-8037-12a92e92b6a1', '1f2232c2-daa4-5614-9be4-ce5c7b8d8565', 'Army', 'officer', '26B', 'DATA SYSTEMS ENGINEERING', 'development', 'O-4', null, 'Major — Typical Developmental Assignments', 'Data Network Engineering Functional Area (FA26) career pamphlet, DA PAM 600-3 chapter (24 July 2026)', 'All FA 26 positions are KD assignments. Officers should strive to complete an aggregate of 24 to 36 months in typical developmental assignments before competing for TWI or ACS. Typical developmental assignments at Major include:', 'e69090a88beb9b7791b9695bcdb410c9ba737c340ab5a282b2f6773c36d3e21a', 8, 8, null, 30, null, null, false, null),
  ('e26673d2-473b-52b7-8442-cec150530b7f', '1f2232c2-daa4-5614-9be4-ce5c7b8d8565', 'Army', 'officer', '26B', 'DATA SYSTEMS ENGINEERING', 'development', 'O-4', null, 'Major — AOC 26A', 'Data Network Engineering Functional Area (FA26) career pamphlet, DA PAM 600-3 chapter (24 July 2026)', '(a) Sr Network Sys Engr in a DIV, Corps, ASCC, COCOM, Signal BDE or CMD, MI BDE, RCC, NETCOM, ARCYBER, DISA, Joint or Higher
(b) 60th Signal BN (Offensive Cyber Operations)
(c) COIC
(d) Requirements Officer, Future Capabilities Development Command and Control (FCD C2)
(e) White House Communications Agency (WHCA)
(f) North American Aerospace Defense Command
(g) Sr Network Systems Engineer, Program Executive Office (PEO), Enterprise Info Sys
(h) USA AI2C', '072859842a7327640e6c49dc8331cec888a89795d0a56ef2ef110056bd80d335', 8, 8, null, 31, null, null, false, null),
  ('431d4d16-cf9b-5fd9-93f8-f5af772868b8', '1f2232c2-daa4-5614-9be4-ce5c7b8d8565', 'Army', 'officer', '26B', 'DATA SYSTEMS ENGINEERING', 'development', 'O-4', null, 'Major — AOC 26B', 'Data Network Engineering Functional Area (FA26) career pamphlet, DA PAM 600-3 chapter (24 July 2026)', '(a) Sr Data Sys Engr in a Division, Corps, ASCC, Signal BDE or CMD, MI BDE, NETCOM, DISA
(b) 60th Signal BN (Offensive Cyber Operations)
(c) COIC
(d) Sr Info Sys Engr, FCD-C2
(e) Sr Information Assurance Officer in a DIV, Sustainment CMD, ASCC, RCC
(f) WHCA
(g) National Ground Intelligence Center (NGIC)
(h) USA ECMA', 'f4cd4e0b8aa9ecaf64bae3a809c0ac2ac950f6881a0d3ed0810266ef153d0536', 8, 8, null, 32, null, null, false, null),
  ('d0a52376-9c65-5f7f-acf9-52270b059f6f', '1f2232c2-daa4-5614-9be4-ce5c7b8d8565', 'Army', 'officer', '26B', 'DATA SYSTEMS ENGINEERING', 'assignments', 'O-4', null, 'Major — Developmental Assignments', 'Data Network Engineering Functional Area (FA26) career pamphlet, DA PAM 600-3 chapter (24 July 2026)', 'AOC 26A majors’ training, education, and development should focus on data network engineering. AOC 26B majors’ training, education, and development should focus on data systems engineering. Due to the technical nature of these AOCs, AOC 26A and AOC 26B majors usually will not serve in branch immaterial or other assignments outside of the AOC. Generally, FA 26 majors should not seek repetitive assignments as FA 26, striving for various experiences at different levels of operation (e.g., tactical, operational, strategic, joint, and multi-national). Majors may be selected for fully funded ACS or TWI programs. Graduates of either program will incur a follow-on utilization assignment. FA 26 majors with operational experience are well suited for assignments in support of career field growth and personnel management, including Career Managers, Career Program Managers and Instructors at USMA and the US Army Signal School. FA 26 officers are encouraged to seek opportunities that enhance the officer’s understanding of the global network environment associated with JADO assignments. Additional education opportunities include the Defense Advanced Research Projects Agency (DARPA) Service Chiefs Internship and other Army-supported education/fellowship programs.', 'd2be4f1b05b8a702fc0c721e33ae1145f259927d81a43b3eddc390dea5cf69f9', 8, 9, null, 33, null, null, false, null),
  ('aa077301-1ecf-5b55-9985-34dda3ff8870', '1f2232c2-daa4-5614-9be4-ce5c7b8d8565', 'Army', 'officer', '26B', 'DATA SYSTEMS ENGINEERING', 'self_development', 'O-4', null, 'Major — Self-development', 'Data Network Engineering Functional Area (FA26) career pamphlet, DA PAM 600-3 chapter (24 July 2026)', 'FA 26 majors should continue to pursue self-development in accordance with assignment, unit mission and equipment, education, and emerging technologies. AOC 26A should pursue self- development in the areas of hybrid software defined networks, and unified network platforms along with developing a holistic vision of a zero-trust infrastructure designed to drive the integration of communication and computing resources in a continuous data-centric network fabric. AOC 26B majors should pursue self- development in the areas of data architecture, artificial intelligence, and machine learning along with developing a holistic vision of cloud architecture and database structure which enable the development and management of total data systems.', 'caf92a6451a980933f946ba2aae4c6e1f0ba62f33901b86fa3de93d4e270f61d', 9, 9, null, 34, null, null, false, null),
  ('7f3c9412-29c6-55d5-a19e-abd09eb3c138', '1f2232c2-daa4-5614-9be4-ce5c7b8d8565', 'Army', 'officer', '26B', 'DATA SYSTEMS ENGINEERING', 'development', 'O-4', null, 'Major — Desired Experience', 'Data Network Engineering Functional Area (FA26) career pamphlet, DA PAM 600-3 chapter (24 July 2026)', '(a) AOC 26A majors should demonstrate competency and advanced skills in network engineering, assessment, managing, planning, and experience in conducting current network operations and defending/securing networks. In addition, field grade development should enable AOC 26As to hone knowledge, skills, and abilities in accurately evaluating technologies and preparing technical specification documents based on these evaluations. Successful completion of ILE and 24 to 36 months of experience in increasing responsibility and professional development assignments will prepare majors for service as a lieutenant colonel.
(b) AOC 26B majors should demonstrate competency and advanced skills in data architecture planning and development and implementation of information assurance concepts and principles. Field grade development should enable AOC 26Bs to hone knowledge, skills, and abilities to perform system analysis, develop response procedures, perform accreditation processes, and integrate data and IT systems in all JADO environments. Successful completion of ILE and 24 to 36 months of experience in increasing responsibility and professional development assignments will prepare majors for service as a lieutenant colonel.', 'd3e1cb9612076a7cb29cce87981640142621cd0e3b8b6194628671367a1c3fc0', 9, 9, null, 35, null, null, false, null),
  ('d143290a-f9ae-5eb3-b6cc-28c6609dd2b2', '1f2232c2-daa4-5614-9be4-ce5c7b8d8565', 'Army', 'officer', '26B', 'DATA SYSTEMS ENGINEERING', 'training', 'O-5', null, 'Lieutenant Colonel — Education', 'Data Network Engineering Functional Area (FA26) career pamphlet, DA PAM 600-3 chapter (24 July 2026)', 'There are no additional educational requirements for lieutenant colonels, however, a Master of Science degree in an IT-related field is highly encouraged. Successful completion of JPME II is desired.', 'a64b2d1b55128ae435cee73cc2bef5329e814247f94b74ce7578053c7bfe014e', 9, 9, null, 36, null, null, false, null),
  ('1f19d6a7-db01-594f-ac87-9f3fcb9b9680', '1f2232c2-daa4-5614-9be4-ce5c7b8d8565', 'Army', 'officer', '26B', 'DATA SYSTEMS ENGINEERING', 'development', 'O-5', null, 'Lieutenant Colonel — Typical Developmental Assignments', 'Data Network Engineering Functional Area (FA26) career pamphlet, DA PAM 600-3 chapter (24 July 2026)', 'All FA 26 lieutenant colonel positions are considered KD assignments. Certain positions are designated as Key Nominative Billets (KNB) or Centralized Selection List (CSL) billets, and officers are centrally selected to fill these positions. Eligible officers will be notified by MILPER message and are encouraged to compete when in the zone of consideration for these assignments. Officers should strive to complete an aggregate of 24 to 36 months in typical developmental assignments before consideration for more senior lieutenant colonel assignments. Typical developmental, CSL or KNB assignments at lieutenant colonel include:', '796b883f40cf4d3ad75554fd7d0c7aa1f421f76f139ebcb40404121d4cec7a2a', 9, 9, null, 37, null, null, false, null),
  ('597785b2-f583-57e7-a3c1-ef9c36fe1a12', '1f2232c2-daa4-5614-9be4-ce5c7b8d8565', 'Army', 'officer', '26B', 'DATA SYSTEMS ENGINEERING', 'development', 'O-5', null, 'Lieutenant Colonel — CSL for AOC 26A and AOC 26B', 'Data Network Engineering Functional Area (FA26) career pamphlet, DA PAM 600-3 chapter (24 July 2026)', 'Director, Regional Cyber Center (RCC)', '126adb863ef6458efd1e23b422d5f156e7312e21b77fe5249bc2f953e7e91651', 9, 9, null, 38, null, null, false, null),
  ('57708ede-6485-5474-b499-a00eef1fea8e', '1f2232c2-daa4-5614-9be4-ce5c7b8d8565', 'Army', 'officer', '26B', 'DATA SYSTEMS ENGINEERING', 'development', 'O-5', null, 'Lieutenant Colonel — AOC 26A', 'Data Network Engineering Functional Area (FA26) career pamphlet, DA PAM 600-3 chapter (24 July 2026)', '(a) Chief Network Sys Engr in a Corps, ASCC, Signal Brigade, RCC, NETCOM, ARCYBER, DISA, COCOM, Joint, DOD Level
(b) COIC
(c) The Office of the Chief Information Officer
(d) Chief, Network & Cyber Branch, USA JMC
(e) Sr. Test Officer, USA Operational Test Command
(f) USA AI2C', '9b5db754545126e62d0d23248e543f6e513140152bcfd2b4bd93b396ed6092e6', 9, 9, null, 39, null, null, false, null),
  ('5b3674b4-337d-5f02-8bda-7e3bac8aef3d', '1f2232c2-daa4-5614-9be4-ce5c7b8d8565', 'Army', 'officer', '26B', 'DATA SYSTEMS ENGINEERING', 'development', 'O-5', null, 'Lieutenant Colonel — AOC 26B', 'Data Network Engineering Functional Area (FA26) career pamphlet, DA PAM 600-3 chapter (24 July 2026)', '(a) Chief Data Sys Engr or Chief Info Assurance Officer in a Corps, ASCC, Signal BDE, NETCOM, DISA, or higher CMD
(b) COIC
(c) The Office of the Chief Information Officer
(d) USA JMC, Branch Chief MSN CMD SYS & APPS
(e) John F. Kennedy Special Warfare Center and School, G6/CIO
(f) National Defense University Military Faculty
(g) USA Futures CMD Application Group (SWFAC)', '3e9cadeae024577f8b1564d17321119fa92f974bad29ea3492d50bc7af44dd4f', 9, 10, null, 40, null, null, false, null),
  ('78c8ec58-3260-576f-97c2-7629ff8bcc35', '1f2232c2-daa4-5614-9be4-ce5c7b8d8565', 'Army', 'officer', '26B', 'DATA SYSTEMS ENGINEERING', 'assignments', 'O-5', null, 'Lieutenant Colonel — Developmental Assignments', 'Data Network Engineering Functional Area (FA26) career pamphlet, DA PAM 600-3 chapter (24 July 2026)', 'Generally, FA 26 lieutenant colonels should not continue to seek repetitive assignments in their AOC, striving for various experiences at different levels of operation and concentrating their professional development in network systems engineering and data systems engineering. At lieutenant colonel, FA 26 officers may obtain developmental experience through TWI and Army fellowships. Select AOC 26A/B officers may serve developmental assignments within branch immaterial positions or related cross- branch/FA positions within the Signal Regiment. Based upon requirements, AOC 26A/B lieutenant colonels might be selected as Professors of Military Science. In addition, some AOC 26A/B lieutenant colonels may be chosen to participate in an IT-related Ph.D. program. All FA 26 officers are encouraged to seek developmental opportunities that enhance the officers’ understanding of the global network environment associated with JADO assignments to include achieving Joint Qualified Officer status. Additional education opportunities include the DARPA Service Chiefs Internship and DARPA Program Manager and other Army-supported education/fellowship programs.', 'e2f47be8973b38f07b01eab0176b2af1b78a5ac20c1e92efc374d250ab5a30b0', 10, 10, null, 41, null, null, false, null),
  ('76dd7452-c1c6-58cc-9bd1-204ca333d8a0', '1f2232c2-daa4-5614-9be4-ce5c7b8d8565', 'Army', 'officer', '26B', 'DATA SYSTEMS ENGINEERING', 'self_development', 'O-5', null, 'Lieutenant Colonel — Self-development', 'Data Network Engineering Functional Area (FA26) career pamphlet, DA PAM 600-3 chapter (24 July 2026)', 'AOC 26A lieutenant colonels should pursue aggressive self-development through graduate-level education, industry certifications, and completion of online training and courses related to networking, computer science, cyberspace operations, cybersecurity, and other relevant disciplines. Lieutenant colonels need to stay current on industry trends through trade associations, journals, and participation in DOD and industry-sponsored forums focused on evolving IT issues and advancements. Lieutenant colonels are also encouraged to research and write articles for professional and military publications. AOC 26B lieutenant colonels should complete the CIO, or CISO course offered free by the National Defense University, College either in resident or nonresident attendance. No-cost IT training is available through the Federal Virtual Training Environment (https://fedvte.usalearning.gov/). It is also encouraged that officers obtain the ITIL Foundations certification. Additional cost and no-cost IT training and education courses are available via the internet and Army COOL at https://www.cool.osd.mil/army/index.htm. Some officers may pursue a Ph.D. in a STEM discipline but prefer an IT-related discipline.', 'd0cd2314d3bd76bf5789fa40aa993c4e7d5c4b5d846294949a7c4442a3a0b9d2', 10, 10, null, 42, null, null, false, null),
  ('96555b4b-cd4d-5769-9f07-c7e52bfa0722', '1f2232c2-daa4-5614-9be4-ce5c7b8d8565', 'Army', 'officer', '26B', 'DATA SYSTEMS ENGINEERING', 'development', 'O-5', null, 'Lieutenant Colonel — Desired Experience', 'Data Network Engineering Functional Area (FA26) career pamphlet, DA PAM 600-3 chapter (24 July 2026)', 'FA26 lieutenant colonels are highly encouraged to plan for and participate in the CSL process to compete for challenging yet impactful assignments. As the Army navigates the landscape of data- centric operations and establishes the Unified Network, FA 26 officers are uniquely qualified to hold specific positions that require both technical expertise and traditional leadership skills. While not prescribed for career development, performing well in CSL positions will positively position competitive FA26 officers for promotion to colonel and beyond.
(a) AOC 26A lieutenant colonels should demonstrate a high degree and mastery of telecommunications systems engineering. AOC 26A officers in the grade of lieutenant colonels serve as senior leaders and managers throughout the Army providing technical engineering guidance, applying network integration experience, emerging technology vision, and overall, Soldier mentorship mastered over many years in uniform as a network engineer. Assignments of increasing responsibility will continue to enhance their leadership skills and technical competencies in leading, managing, and integrating enterprise-wide communications networks and information services for the Army and JADO organizations.
(b) AOC 26B lieutenant colonels should continue to broaden their experiences and seek assignments that enhance their technical skills, knowledge, and executive leadership abilities. They are generally assigned to senior leadership and staff positions that fully utilize their Army knowledge and data systems engineering experience. AOC 26B lieutenant colonels should strive to serve in assignments that will broaden their previous experience through leading organizations that provide data systems and services throughout the Army and JADO organizations. They should demonstrate expertise in performing system analysis, developing and planning data architectures, implementing information assurance concepts and principles, and developing response procedures.', '35a80944d04edf6a5bb5252fb5c53397923113dec5e4cc601d757e22466dbc88', 10, 10, null, 43, null, null, false, null),
  ('4e777c7c-ea73-5328-840f-6d7fc612a189', '1f2232c2-daa4-5614-9be4-ce5c7b8d8565', 'Army', 'officer', '26Z', 'DATA NETWORK ENGINEERING', 'training', 'O-6', null, 'AOC 26Z Colonels — Education', 'Data Network Engineering Functional Area (FA26) career pamphlet, DA PAM 600-3 chapter (24 July 2026)', 'AOC 26Z colonels are highly encouraged to complete resident or non-resident Senior Service College. Successful completion of JPME II is desired.', '0deedf934bb2dd60c6b5dfa8d2ae4e0da9156965b72d148564952123c6a9db32', 10, 10, null, 44, null, null, false, null),
  ('5526b5e6-7671-57c1-b311-8be7113d69a6', '1f2232c2-daa4-5614-9be4-ce5c7b8d8565', 'Army', 'officer', '26Z', 'DATA NETWORK ENGINEERING', 'development', 'O-6', null, 'AOC 26Z Colonels — Typical Developmental Assignments', 'Data Network Engineering Functional Area (FA26) career pamphlet, DA PAM 600-3 chapter (24 July 2026)', 'All AOC 26Z COL positions are considered KD assignments. Certain positions such as RCC Director are designated as KNB or CSL billets, and officers are centrally selected to fill these positions. Eligible officers will be notified by MILPER message and are encouraged to compete within the zone of consideration for these assignments. Officers should strive to complete an aggregate of 24 to 36 months in typical developmental assignments. Typical developmental or KNB/CSL(*) assignments at colonel include:
(a) *Commander, Command and Control Support Agency, HQDA G3/5/7.
(b) *TRADOC Proponent Office Army Training Information Systems (TPO ATIS).
(c) *CDR, ISEC
(d) Chief, Tactical Network Integration Division, Office of Deputy Chief of Staff, G6
(e) Chief Information Officer/Chief Technology Officer at Army or Joint Staff
(f) Commander, NATO Communications and Information Agency
(g) Director/Dep Director at ASCC, DRU, HQDA, Joint, DOD level, Multinational
(h) Division Chief, Plans & Strategy, Office of the Chief Information Officer (OCIO)
(i) Executive assistant at ASCC, DRU, HQDA, Joint, DOD level, Multinational
(j) G6, Cyber Center of Excellence (CCoE)
(k) Sr. Staff Analyst at ASCC, DRU, HQDA, Joint, DOD level, Multinational
(l) USA Communication Info System Activity, Pacific
(m) USA Inspector General Agency', 'eb01322c74c59cf3fd54122f1aed437b17acba4cfc35314200a81d0e22353184', 10, 11, null, 45, null, null, false, null),
  ('3815a2fb-d7d6-5a3d-adc8-d5e64324a191', '1f2232c2-daa4-5614-9be4-ce5c7b8d8565', 'Army', 'officer', '26Z', 'DATA NETWORK ENGINEERING', 'assignments', 'O-6', null, 'AOC 26Z Colonels — Developmental Assignments', 'Data Network Engineering Functional Area (FA26) career pamphlet, DA PAM 600-3 chapter (24 July 2026)', 'AOC 26Z colonels should serve in AOC 26Z or AOC 25A assignments and strive to achieve a variety of executive-level engineering leadership experiences in Army, joint, and multinational organizations. Additionally, selected officers may serve additional assignments within branch immaterial positions or related cross-branch/FA positions. Joint experience is essential to the Army and is highly desirable for individual officers to compete for advancement into senior leadership positions.', '17d296a72010b967d9d962b71814cf5fe849acd6023db59871b309aae4479528', 11, 11, null, 46, null, null, false, null),
  ('41c86fff-5379-51ac-b6ae-2918d7b6f5c1', '1f2232c2-daa4-5614-9be4-ce5c7b8d8565', 'Army', 'officer', '26Z', 'DATA NETWORK ENGINEERING', 'self_development', 'O-6', null, 'AOC 26Z Colonels — Self-Development', 'Data Network Engineering Functional Area (FA26) career pamphlet, DA PAM 600-3 chapter (24 July 2026)', 'All AOC 26Z colonels should continue to pursue continuing graduate-level education and industry certifications. Officers also need to stay current on industry trends through trade associations, journals, and participation in DOD and industry-sponsored forums focused on evolving IT issues and advances. Some candidates may pursue completion of a Ph.D. in an IT-related discipline.', '175422922c44c1a26e9b91962f26b7c924fa4fae336187d211f7db1633efea0f', 11, 11, null, 47, null, null, false, null),
  ('5cd00bf2-b942-577f-b799-f9821cc90180', '1f2232c2-daa4-5614-9be4-ce5c7b8d8565', 'Army', 'officer', '26Z', 'DATA NETWORK ENGINEERING', 'development', 'O-6', null, 'AOC 26Z Colonels — Desired Experience', 'Data Network Engineering Functional Area (FA26) career pamphlet, DA PAM 600-3 chapter (24 July 2026)', 'As senior practitioners in AOC 26Z, colonels constitute the elite of the data network engineering officer corps. Years of accumulated training, education, and progressive assignments provide a level of expertise that enables 26Z officers to serve in strategic leadership positions at all levels of Army, Joint, and DOD staff. The AOC 26Z colonels should strive for assignments that balance and round out their field grade experience with a mix of tactical, operational, and strategic assignments. Selected officers may be assigned to high-performance AOC 26Z colonel positions as determined by the Chief of Staff of the Army. Successful completion of SSC plus 24 to 36 months of AOC 26Z experience will prepare colonels for service at the next higher grade. Field grade assignments should include Army Staff, joint, and operational deployment experiences alongside successful CSL or KNB assignments to be competitive for selection to general officer.', '7be16a594b7b67d4612df0d8d122fa8ee33ccb37eb462d3b094b6835471d229f', 11, 11, null, 48, null, null, false, null);
